func TestNoAgreementIsThScore(emonT *testing.T) {
	// the font score without agreement is P7.0's, on a grid of components
	var m int32 = 1000
	var g int32 = 0
	var o int32 = 0
	var p int32 = 0
	for m >= 0 {
		g = 0
		for g <= 1000 {
			o = 0
			for o <= 1000 {
				p = 0
				for p <= 4000 {
					port.AssertEq(emonT, health.HhScore(m, g, o, p, -1), tlhealth.ThScore(m, g, o, p), "hh-score is th-score without agreement")
					p += 1333
				}
				o += 250
			}
			g += 250
		}
		m -= 333
	}
}

func TestBlend(emonT *testing.T) {
	port.AssertEq(emonT, health.HhBlend(1000, 4, 1000, 3, 1000, 2, 1000, 1, 1000, 5, -1, 0), 1000, "all perfect")
	port.AssertEq(emonT, health.HhBlend(-1, 4, -1, 3, -1, 2, -1, 1, -1, 5, -1, 0), -1, "nothing present")
	// an absent component is ignored, never zero
	port.AssertEq(emonT, health.HhBlend(800, 3, -1, 3, -1, 2, -1, 2, -1, 0, -1, 0), 720, "one present: its own value, scaled by the weakest, which it is")
	port.AssertEq(emonT, health.HhBlend(1000, 3, 1000, 3, -1, 2, 1000, 2, -1, 0, -1, 0), 1000, "the absent one does not drag")
	// the weakest scales the harmonic mean: 15e6 / (10000 + 5e6/100) = 250, times (1000 + 100) / 2000
	port.AssertEq(emonT, health.HhBlend(1000, 4, 1000, 3, 1000, 2, 1000, 1, 100, 5, -1, 0), 137, "one weak component pulls the whole down")
	// agreement 0 is floored at 50 for the mean and counts as 0 for the scale
	port.AssertEq(emonT, health.HhBlend(1000, 4, 1000, 3, 1000, 2, 1000, 1, 0, 5, -1, 0), 68, "no agreement at all")
	port.AssertEq(emonT, health.HhScore(1000, 0, 0, 0, 900), 1000, "agreement 900 is fully trusted")
	port.AssertEq(emonT, health.HhScore(1000, 0, 0, 0, 100), 68, "agreement 100 is under the bad line: the same as none at all")
	port.AssertEq(emonT, health.HhOcrScore(1000, 1000, -1, 1000, -1, -1), 1000, "a clean block")
	port.AssertEq(emonT, health.HhRegionScore(-1, -1, 1000, 900), 899, "a region with only skew and confidence: 947 scaled by 0.95")
}

func htWordIn(words *port.Cells, fw *port.Cells, feats *port.Cells, et *port.Cells, page int32, font int32, script int32) int32 {
	// One text-layer word of `page` in `font`, its feature row of the `xt` columns a healthy font has, copied into `fw`; answers its `fw` row.
	var ts int32 = port.CellsLen(et)
	var w int32 = evidence.WdNew(words, page, 0, 0, 1000, 1000, 0, 900, 1000, 900, 0, 0, ts, 2, -1, -1, -1)
	var f int32 = evidence.FeNew(feats, evidence.EaWords(), w)
	var r int32 = 0
	if script == 0 {
		port.CellsPush(et, 97)
		port.CellsPush(et, 98)
	} else if script == 2 {
		port.CellsPush(et, 1488)
		port.CellsPush(et, 49)
	} else {
		port.CellsPush(et, 1488)
		port.CellsPush(et, 1489)
	}
	evidence.WdSet(words, w, evidence.WfFont(), font)
	evidence.FeSet(feats, f, evidence.XtFontHealth(), 1000)
	evidence.WdSet(words, w, evidence.HdFeat(), f)
	r = port.CellsLen(fw) / 24
	player.FwCopyWord(fw, words, w, -1)
	return r
}

func htWord(words *port.Cells, fw *port.Cells, feats *port.Cells, et *port.Cells, page int32, font int32) int32 {
	return htWordIn(words, fw, feats, et, page, font, 0)
}

func htFontRow(hl *port.Cells, page int32, font int32) int32 {
	// A font-page row of P7.0's: components of a healthy font, score 1000.
	var r int32 = player.HlNew(hl, player.PlhFontPage(), page, font)
	player.HlSet(hl, r, player.HlfMapped(), 1000)
	player.HlSet(hl, r, player.HlfGarbage(), 0)
	player.HlSet(hl, r, player.HlfOverlap(), 0)
	player.HlSet(hl, r, player.HlfGap(), 0)
	player.HlSet(hl, r, player.HlfScore(), 1000)
	return r
}

func htGroup(cg *port.Cells, refs *port.Cells, page int32, ea int32, widx int32, simfold int32) int32 {
	// A group of `page` with one text-layer candidate (the `ea` row `widx`) and one OCR word; its folded similarity.
	var g int32 = player.CgNew(cg, page, 0, 0, 1000, 1000, 0)
	var t int32 = evidence.RfAdd(refs, ea, widx)
	var o int32 = evidence.RfAdd(refs, evidence.EaOwords(), 0)
	player.CgSet(cg, g, player.CgfTfirst(), t)
	player.CgSet(cg, g, player.CgfTcount(), 1)
	player.CgSet(cg, g, player.CgfOfirst(), o)
	player.CgSet(cg, g, player.CgfOcount(), 1)
	player.CgSet(cg, g, player.CgfSimfold(), simfold)
	return g
}

func htGroups(cg *port.Cells, refs *port.Cells, page int32, ea int32, widx int32, total int32, agreeing int32) int32 {
	// `total` groups on one word, the first `agreeing` of them at similarity 950, the rest at 100.
	var i int32 = 0
	for i < total {
		if i < agreeing {
			htGroup(cg, refs, page, ea, widx, 950)
		} else {
			htGroup(cg, refs, page, ea, widx, 100)
		}
		i += 1
	}
	return total
}

func htScoreOf(hl *port.Cells, page int32, font int32) int32 {
	var n int32 = player.HlCount(hl)
	var i int32 = 0
	for i < n {
		if (player.HlGet(hl, i, 0) == player.PlhFontPage()) && ((player.HlGet(hl, i, 1) == page) && (player.HlGet(hl, i, 2) == font)) {
			return player.HlGet(hl, i, player.HlfScore())
		}
		i += 1
	}
	return -2
}

