func TestAHealthyFontAndAShiftedOne(emonT *testing.T) {
	var words *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var cg *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var hl *port.Cells = port.NewCells()
	var ob *port.Cells = port.NewCells()
	var ol *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var healthy int32 = htWord(words, fw, feats, et, 1, 0)
	var shifted int32 = htWord(words, fw, feats, et, 1, 1)
	htFontRow(hl, 1, 0)
	htFontRow(hl, 1, 1)
	// font 0: 12 groups, 11 agree; font 1: 12 groups, 1 agrees
	htGroups(cg, refs, 1, player.PlEaFw(), healthy, 12, 11)
	htGroups(cg, refs, 1, player.PlEaFw(), shifted, 12, 1)
	health.HlPage(1, cg, refs, fw, words, et, feats, ob, ol, ow, hl)
	port.AssertEq(emonT, htAgreementOf(hl, 1, 0), 916, "11 of 12")
	port.AssertEq(emonT, htAgreementOf(hl, 1, 1), 83, "1 of 12")
	port.AssertThat(emonT, htScoreOf(hl, 1, 0) >= tlhealth.ThTrusted(), "the healthy font is trusted")
	port.AssertThat(emonT, htScoreOf(hl, 1, 1) < 300, "the shifted font is under 300")
	port.AssertEq(emonT, evidence.FeGet(feats, 0, evidence.XtFontHealth()), htScoreOf(hl, 1, 0), "its word's column 13")
	port.AssertEq(emonT, evidence.FeGet(feats, 1, evidence.XtFontHealth()), htScoreOf(hl, 1, 1), "the shifted word's column 13")
	// the groups it was made of
	port.AssertEq(emonT, player.HlGet(hl, 1, health.HlfBoth()), 12, "groups with both")
	port.AssertEq(emonT, player.HlGet(hl, 1, health.HlfAgree()), 1, "agreeing groups")
	// a second call is the same
	health.HlPage(1, cg, refs, fw, words, et, feats, ob, ol, ow, hl)
	port.AssertEq(emonT, player.HlCount(hl), 2, "no row is added")
	port.AssertEq(emonT, htAgreementOf(hl, 1, 1), 83, "and no count doubles")
}

