func htOcrWord(ow *port.Cells, feats *port.Cells, length int32, ink int32, implausible int32, body int32, seal int32, artifact int32) int32 {
	// An OCR word whose feature row has these columns (-1 leaves one absent) and an engine confidence of 0, which means nothing.
	var w int32 = evidence.OwNew(ow, 1, 0, 0, 1000, 1000, 0, 900, 1000, 900, 0, 0, 0, length, -1, 0, -1)
	var f int32 = evidence.FeNew(feats, evidence.EaOwords(), w)
	evidence.OwSet(ow, w, evidence.HdFeat(), f)
	evidence.FeSet(feats, f, evidence.XoConf(), 0)
	evidence.FeSet(feats, f, evidence.XoLength(), length)
	evidence.FeSet(feats, f, evidence.XoKinInk(), ink)
	evidence.FeSet(feats, f, evidence.XoImplausible(), implausible)
	evidence.FeSet(feats, f, evidence.XoBodyShare(), body)
	evidence.FeSet(feats, f, evidence.XoSeal(), seal)
	evidence.FeSet(feats, f, evidence.XoArtifact(), artifact)
	return f
}

func htBlock(ob *port.Cells, ol *port.Cells, firstWord int32, nwords int32) int32 {
	// A block of one paragraph of one line over `nwords` words from `first-word`; answers the block's row.
	var line int32 = evidence.OlNew(ol, 1, 0, 0, 1000, 1000, 0, 900, 1000, 900, 0, 0, firstWord, nwords)
	var b int32 = evidence.ObNew(ob, 1, 0, 0, 1000, 1000, evidence.ObBlock(), -1, 0)
	var p int32 = evidence.ObNew(ob, 1, 0, 0, 1000, 1000, evidence.ObParagraph(), b, 0)
	evidence.ObSet(ob, b, evidence.ObfFirst(), p)
	evidence.ObSet(ob, b, evidence.ObfCount(), 1)
	evidence.ObSet(ob, p, evidence.ObfFirst(), line)
	evidence.ObSet(ob, p, evidence.ObfCount(), 1)
	return b
}

func htBlockScore(hl *port.Cells, b int32) int32 {
	var n int32 = player.HlCount(hl)
	var i int32 = 0
	for i < n {
		if (player.HlGet(hl, i, 0) == player.PlhOcrBlock()) && (player.HlGet(hl, i, 2) == b) {
			return i
		}
		i += 1
	}
	return -1
}

func htBget(hl *port.Cells, b int32, field int32) int32 {
	// Cell `field` of the health row of OCR block `b`.
	var r int32 = htBlockScore(hl, b)
	return player.HlGet(hl, r, field)
}

func TestOcrBlocks(emonT *testing.T) {
	var words *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var cg *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var hl *port.Cells = port.NewCells()
	var ob *port.Cells = port.NewCells()
	var ol *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	// block 0: body text (ink 150, nothing implausible, 95 % on the body layer, no seal, no artifact); 1: over blank paper;
	// 2: under a seal; 3: soup; 4: watermark (artifact 900, light ink); 5: no ink columns at all, only the plausibility
	htOcrWord(ow, feats, 5, 150, 0, 950, 0, 0)
	htOcrWord(ow, feats, 6, 140, 0, 960, 0, 0)
	htBlock(ob, ol, 0, 2)
	htOcrWord(ow, feats, 6, 2, 0, 0, 0, 0)
	htBlock(ob, ol, 2, 1)
	htOcrWord(ow, feats, 6, 150, 0, 100, 900, 0)
	htBlock(ob, ol, 3, 1)
	htOcrWord(ow, feats, 6, 150, 800, 950, 0, 0)
	htBlock(ob, ol, 4, 1)
	htOcrWord(ow, feats, 6, 40, 0, 100, 0, 900)
	htBlock(ob, ol, 5, 1)
	htOcrWord(ow, feats, 6, -1, 0, -1, -1, -1)
	htBlock(ob, ol, 6, 1)
	port.AssertEq(emonT, health.HlPage(1, cg, refs, fw, words, et, feats, ob, ol, ow, hl), 6, "six blocks scored")
	port.AssertEq(emonT, player.HlCount(hl), 6, "and six rows")
	var body int32 = htBget(hl, 0, player.HlfScore())
	var blank int32 = htBget(hl, 2, player.HlfScore())
	var seal int32 = htBget(hl, 4, player.HlfScore())
	var soup int32 = htBget(hl, 6, player.HlfScore())
	var mark int32 = htBget(hl, 8, player.HlfScore())
	var bare int32 = htBget(hl, 10, player.HlfScore())
	port.AssertThat(emonT, body >= 900, "a body block is trusted")
	port.AssertThat(emonT, blank < body, "blank paper scores under the body")
	port.AssertThat(emonT, seal < body, "a seal scores under the body")
	port.AssertThat(emonT, soup < body, "soup scores under the body")
	port.AssertThat(emonT, mark < body, "a watermark scores under the body")
	port.AssertThat(emonT, blank < 300, "blank paper is far under")
	port.AssertThat(emonT, seal < 300, "a seal is far under")
	port.AssertEq(emonT, bare, 1000, "a block with only a plausibility is scored on it: what is absent does not drag")
	port.AssertEq(emonT, htBget(hl, 0, health.HobSeal()), 1000, "the body's seal component: 1000 - 0")
	port.AssertEq(emonT, htBget(hl, 4, health.HobSeal()), 100, "the seal block's: 1000 - 900")
	port.AssertEq(emonT, htBget(hl, 4, health.HobBody()), 100, "and its body share")
	port.AssertEq(emonT, htBget(hl, 8, health.HobArtifact()), 100, "the watermark's artifact component")
	port.AssertEq(emonT, htBget(hl, 10, health.HobInk()), -1, "an absent column is -1")
	port.AssertEq(emonT, htBget(hl, 10, health.HobSeal()), -1, "and stays absent")
	port.AssertEq(emonT, htBget(hl, 10, health.HobPlausible()), 1000, "while the plausibility is there")
	port.AssertEq(emonT, htBget(hl, 0, health.HobScript()), -1, "no script column: ignored")
	port.AssertEq(emonT, htBget(hl, 0, health.HobPlausible()), 1000, "the body's plausibility")
	port.AssertEq(emonT, htBget(hl, 0, health.HobInk()), 1000, "the body's ink support: 150 is over `ink-ok`")
	port.AssertEq(emonT, htBget(hl, 2, health.HobInk()), 0, "blank paper's: 2 is under `ink-bad`")
	// a second call overwrites
	health.HlPage(1, cg, refs, fw, words, et, feats, ob, ol, ow, hl)
	port.AssertEq(emonT, player.HlCount(hl), 6, "no row is added")
}

func htRule(rl *port.Cells, page int32, x0 int32, y0 int32, x1 int32, y1 int32, conf int32) int32 {
	var r int32 = evidence.RlNew(rl, page, x0-0, y0-0, x1, y1, 0)
	evidence.RlSet(rl, r, 6, x0)
	evidence.RlSet(rl, r, 7, y0)
	evidence.RlSet(rl, r, 8, x1)
	evidence.RlSet(rl, r, 9, y1)
	evidence.RlSet(rl, r, evidence.RlfConf(), conf)
	return r
}

func TestRegions(emonT *testing.T) {
	var hl *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var rl *port.Cells = port.NewCells()
	// an image placement of 10 x 10 cm at (10000, 10000); a page of rules outside it, parallel to the axes within 10 centi-degrees
	evidence.ImNew(im, 1, 10000, 10000, 20000, 20000, 5, 800, 800)
	htRule(rl, 1, 1000, 1000, 50000, 1000, 900)
	htRule(rl, 1, 1000, 5000, 50000, 5003, 950)
	htRule(rl, 1, 1000, 1000, 1000, 40000, 850)
	// inside the image: skewed 1.5 degrees, far from parallel to each other
	htRule(rl, 1, 11000, 12000, 19000, 12100, 700)
	htRule(rl, 1, 11000, 15000, 19000, 15000, 700)
	htRule(rl, 1, 12000, 11000, 12150, 19000, 600)
	port.AssertEq(emonT, health.HlRegions(1, im, rl, 920, 960, hl), 2, "R0 and one image")
	port.AssertEq(emonT, player.HlGet(hl, 0, 2), -1, "R0's subject")
	port.AssertEq(emonT, player.HlGet(hl, 0, health.HrgRules()), 3, "three rules outside the image")
	port.AssertEq(emonT, player.HlGet(hl, 0, health.HrgWitness()), 920, "the witness is the caller's")
	port.AssertEq(emonT, player.HlGet(hl, 0, health.HrgPrecision()), 960, "and so is the precision")
	port.AssertEq(emonT, player.HlGet(hl, 0, health.HrgConf()), 900, "the mean confidence of 900, 950, 850")
	port.AssertThat(emonT, player.HlGet(hl, 0, health.HrgSkew()) >= 900, "parallel rules: the skew component is high")
	port.AssertThat(emonT, player.HlGet(hl, 0, player.HlfScore()) >= 800, "R0's score is high")
	port.AssertEq(emonT, player.HlGet(hl, 1, 2), 0, "the image's subject is its row")
	port.AssertEq(emonT, player.HlGet(hl, 1, health.HrgRules()), 3, "three rules inside it")
	port.AssertEq(emonT, player.HlGet(hl, 1, health.HrgWitness()), -1, "no witness of its own")
	port.AssertEq(emonT, player.HlGet(hl, 1, health.HrgPrecision()), 960, "it borrows the page's precision")
	port.AssertEq(emonT, player.HlGet(hl, 1, health.HrgConf()), 666, "the mean of 700, 700, 600")
	port.AssertThat(emonT, player.HlGet(hl, 1, health.HrgSkew()) < 1000, "a spread over 30 centi-degrees costs")
	port.AssertThat(emonT, player.HlGet(hl, 1, player.HlfScore()) < player.HlGet(hl, 0, player.HlfScore()), "the image scores under R0")
	// again: overwritten
	health.HlRegions(1, im, rl, 920, 960, hl)
	port.AssertEq(emonT, player.HlCount(hl), 2, "no row is added")
}

func TestTheTracersSymbolSupportJoinsTheInkSupport(emonT *testing.T) {
	var feats *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	// ink 150 is full support alone; with the tracer saying none of the symbols has a text-like component it is half
	htOcrWord(ow, feats, 5, 150, 0, 1000, 0, 0)
	htOcrWord(ow, feats, 5, 150, 0, 1000, 0, 0)
	evidence.FeSet(feats, 1, evidence.XoCompRatio(), 0)
	htOcrWord(ow, feats, 5, -1, 0, 1000, 0, 0)
	evidence.FeSet(feats, 2, evidence.XoCompRatio(), 400)
	port.AssertEq(emonT, health.HhWordScore(feats, 0), 1000, "the word with ink alone")
	port.AssertThat(emonT, health.HhWordScore(feats, 1) < health.HhWordScore(feats, 0), "the same word with no component in its symbols scores under it")
	port.AssertEq(emonT, health.HhWordScore(feats, 2), 529, "a word with only the tracer's share is scored on it: 14e6 / 18500 = 756, times 1400 / 2000")
	port.AssertEq(emonT, health.HhWordScore(feats, -1), -1, "no feature row: no score")
}
